UNITS = [{'id': 'PEDS-U169', 'ch': 21, 'n': 1, 'title': 'COVID-19 — Guidelines & COVID Appropriate Behaviour', 'sec': 'COVID-19 in Children · p92', 'qs': ['PEDS-C21-001', 'PEDS-C21-002', 'PEDS-C21-003', 'PEDS-C21-004', 'PEDS-C21-005', 'PEDS-C21-006', 'PEDS-C21-007', 'PEDS-C21-008'], 'guide': 'Guidelines for COVID-19 are given by the Ministry of Health & Family Welfare (MoHFW). COVID appropriate behaviour = 3Ws & AVS: Watch your distance (> 2 metres), Wear mask, Wash your hands frequently, Ventilation (open space ventilation ↓ transmission) and Vaccination (for 15–18 years of age).'}, {'id': 'PEDS-U170', 'ch': 21, 'n': 2, 'title': 'COVID-19 Features in Children — Symptoms', 'sec': 'COVID-19 features in children · p92', 'qs': ['PEDS-C21-009', 'PEDS-C21-010', 'PEDS-C21-011', 'PEDS-C21-012', 'PEDS-C21-013', 'PEDS-C21-014', 'PEDS-C21-015', 'PEDS-C21-016', 'PEDS-C21-017', 'PEDS-C21-018'], 'guide': 'Symptoms: Mild/asymptomatic (m/c; incidental detection or h/o contact), fever, cough, rhinorrhoea, sore throat/throat irritation (Omicron variant m/c), myalgia/headache/malaise, diarrhoea, loss of sense of smell > taste (Delta variant m/c).'}, {'id': 'PEDS-U171', 'ch': 21, 'n': 3, 'title': 'Severity Classification, Danger Signs & Tachypnoea Criteria', 'sec': 'Severity table · p92', 'qs': ['PEDS-C21-019', 'PEDS-C21-020', 'PEDS-C21-021', 'PEDS-C21-022', 'PEDS-C21-023', 'PEDS-C21-024', 'PEDS-C21-025', 'PEDS-C21-026', 'PEDS-C21-027', 'PEDS-C21-028', 'PEDS-C21-029', 'PEDS-C21-030', 'PEDS-C21-031', 'PEDS-C21-032'], 'guide': 'Severity: Asymptomatic / Mild (URT) / Moderate / Severe. RR normal in asymptomatic & mild, ↑ in moderate & severe. SpO2 in room air: normal (asymptomatic), > 94% (mild), 90–93% (moderate), < 90% (severe). Danger signs: grunting, lethargy, seizures, somnolence, severe chest retractions — present only in severe. Tachypnoea: < 2 mo > 60/min; 2–12 mo > 50/min; 1–5 yr > 40/min; > 5 yr > 30/min.'}, {'id': 'PEDS-U172', 'ch': 21, 'n': 4, 'title': 'Investigations by Severity of Disease', 'sec': 'Investigations · p93', 'qs': ['PEDS-C21-033', 'PEDS-C21-034', 'PEDS-C21-035', 'PEDS-C21-036', 'PEDS-C21-037', 'PEDS-C21-038', 'PEDS-C21-039', 'PEDS-C21-040'], 'guide': 'Investigations: Asymptomatic/mild — not required. Moderate — CBC, ESR, chest X-ray, blood glucose. Severe — above + CRP/ferritin (markers of inflammation), D-dimer assays (for thrombosis), LFT/RFT (for multi-organ dysfunction). CT chest: not indicated in paediatric COVID, except if terminally ill.'}, {'id': 'PEDS-U173', 'ch': 21, 'n': 5, 'title': 'Treatment — Site of Care & Rx by Severity', 'sec': 'Treatment · p93', 'qs': ['PEDS-C21-041', 'PEDS-C21-042', 'PEDS-C21-043', 'PEDS-C21-044', 'PEDS-C21-045', 'PEDS-C21-046', 'PEDS-C21-047', 'PEDS-C21-048', 'PEDS-C21-049', 'PEDS-C21-050', 'PEDS-C21-051', 'PEDS-C21-052'], 'guide': 'Site of care: Asymptomatic — home isolation. Mild — home isolation ± teleconsultation (sos), COVID care centre. Moderate — ward of a COVID-19 hospital / DCHC (Dedicated COVID Health Centre). Severe — ICU / High Dependency Unit (HDU). Rx: Asymptomatic — no specific Rx. Mild — paracetamol for fever, warm saline gargles for sore throat. Moderate — O2 inhalation (target SpO2 94–96%), fluid & electrolyte balance, steroids in progressive disease, antimicrobials if needed. Severe — O2 support (94–96%), fluid & electrolytes, corticosteroids (most useful drug; indicated in all severe cases).'}, {'id': 'PEDS-U174', 'ch': 21, 'n': 6, 'title': 'Steroid Administration, Anticoagulants, Antimicrobials & Antivirals', 'sec': 'Steroid administration · p93', 'qs': ['PEDS-C21-053', 'PEDS-C21-054', 'PEDS-C21-055', 'PEDS-C21-056', 'PEDS-C21-057', 'PEDS-C21-058', 'PEDS-C21-059', 'PEDS-C21-060', 'PEDS-C21-061', 'PEDS-C21-062'], 'guide': 'Steroids — Right time: avoided in first 3–5 days after onset of symptoms (prolongs viral shedding). Right dose: Dexamethasone 0.15–6 mg/kg once daily; Methylprednisolone 0.75–30 mg/kg once daily. Right duration: 5–7 days → tapered over 10–14 days. Anticoagulants: thrombosis confirmed by imaging/↑ D-dimer — LMWH (Enoxaparin) 1 mg/kg BD. Antimicrobials: clinical evidence/suspicion of bacterial infection, septic shock. Antivirals (Remdesivir, Favipiravir)/monoclonal antibodies: not recommended (efficacy unknown in children).'}, {'id': 'PEDS-U175', 'ch': 21, 'n': 7, 'title': 'MIS-C — Presentation & Risk Factors', 'sec': 'Multisystem inflammatory syndrome in children · p94', 'qs': ['PEDS-C21-063', 'PEDS-C21-064', 'PEDS-C21-065', 'PEDS-C21-066', 'PEDS-C21-067', 'PEDS-C21-068'], 'guide': 'MIS-C (Multisystem inflammatory syndrome in children) presents 2–4 weeks after acute COVID. Risk factors: age < 1 year, co-morbidities (asthma, chronic lung disease), obesity, children with immunodeficiency.'}, {'id': 'PEDS-U176', 'ch': 21, 'n': 8, 'title': 'MIS-C — WHO Diagnostic Criteria & Management', 'sec': 'Diagnostic criteria (WHO) for MIS-C · p94', 'qs': ['PEDS-C21-069', 'PEDS-C21-070', 'PEDS-C21-071', 'PEDS-C21-072', 'PEDS-C21-073', 'PEDS-C21-074', 'PEDS-C21-075', 'PEDS-C21-076', 'PEDS-C21-077', 'PEDS-C21-078', 'PEDS-C21-079', 'PEDS-C21-080', 'PEDS-C21-081', 'PEDS-C21-082'], 'guide': 'WHO criteria: fever > 38°C for ≥ 3 days AND any 2 of — mucocutaneous inflammation (rash/bilateral non-purulent conjunctivitis), hypotension or shock, myocardial dysfunction/myocarditis/valvulitis/coronary aneurysms/↑ troponin, coagulopathy (elevated D-dimers), severe GI involvement (uncontrolled abdominal pain/diarrhoea). Additional: ↑ inflammatory markers (CRP > 5 mg/dl, ESR > 40 mm/hr, procalcitonin), recent COVID (RTPCR +ve)/contact with confirmed case, no evidence of serious bacterial infection/alternative diagnosis. Management: hospitalization in ICU; methylprednisolone 2 mg/kg/day tapered over 2–3 weeks; IVIG 2 g/kg slow IV infusion (maximum 100 g).'}]

